import { Device } from "../utils/Device.js";
import { Helpers } from "../utils/Helpers.js";
import { PerformanceProfile } from "../utils/PerformanceProfile.js";
import type {
  ResponsiveBreakpoint,
  ResponsiveEnvironmentInput,
  ResponsiveListener,
  ResponsiveSnapshot,
} from "../types/runtime.types.js";

const DEFAULT_VIEWPORT_WIDTH = 1440;
const DEFAULT_VIEWPORT_HEIGHT = 900;
const DEFAULT_DEVICE_PIXEL_RATIO = 1;

export class ResponsiveRuntime {
  private _snapshot: ResponsiveSnapshot | null = null;
  private _listeners = new Set<ResponsiveListener>();
  private _reduceMotionMedia: MediaQueryList | null = null;
  private _reduceMotionHandler: (() => void) | null = null;
  private _initialized = false;

  init(): void {
    if (this._initialized) return;
    this._initialized = true;
    this.updateFromWindow();
    this._bindPreferenceListeners();
  }

  dispose(): void {
    if (this._reduceMotionMedia && this._reduceMotionHandler) {
      this._reduceMotionMedia.removeEventListener(
        "change",
        this._reduceMotionHandler,
      );
    }
    this._reduceMotionMedia = null;
    this._reduceMotionHandler = null;
    this._listeners.clear();
    this._initialized = false;
  }

  updateFromWindow(): Readonly<ResponsiveSnapshot> {
    const snapshot = this._createSnapshot();
    this._snapshot = snapshot;
    this._applyCssVariables(snapshot);
    this._listeners.forEach((listener) => listener(snapshot));
    return snapshot;
  }

  getSnapshot(): Readonly<ResponsiveSnapshot> {
    if (!this._snapshot) {
      return this.updateFromWindow();
    }
    return this._snapshot;
  }

  subscribe(listener: ResponsiveListener): () => void {
    this._listeners.add(listener);
    listener(this.getSnapshot());
    return () => {
      this._listeners.delete(listener);
    };
  }

  private _createSnapshot(): ResponsiveSnapshot {
    const device = Device.getDefault();
    device.updateFromWindow();
    const viewportWidth = device.viewportWidth || DEFAULT_VIEWPORT_WIDTH;
    const viewportHeight = device.viewportHeight || DEFAULT_VIEWPORT_HEIGHT;
    const devicePixelRatio =
      typeof window === "undefined"
        ? DEFAULT_DEVICE_PIXEL_RATIO
        : Math.max(1, window.devicePixelRatio || DEFAULT_DEVICE_PIXEL_RATIO);
    const reducedMotion = this._prefersReducedMotion();
    const environment = this._createEnvironmentInput(
      viewportWidth,
      viewportHeight,
      devicePixelRatio,
      device.isMobile,
      reducedMotion,
    );
    const performance = PerformanceProfile.getMainProfile(environment);
    const pixelRatioMax = performance.enginePixelRatioMax;
    const breakpoint = this._resolveBreakpoint(viewportWidth);

    return {
      viewportWidth,
      viewportHeight,
      deviceType: device.deviceType,
      isMobile: device.isMobile,
      breakpoint,
      render: {
        devicePixelRatio,
        pixelRatioMax,
        clampedPixelRatio: Math.min(devicePixelRatio, pixelRatioMax),
      },
      flags: {
        reducedMotion,
        hoverCapable: this._matchesMedia("(hover: hover) and (pointer: fine)"),
        coarsePointer: this._matchesMedia("(pointer: coarse)"),
      },
      performance,
      tokens: {
        viewportScale: this._resolveViewportScale(viewportWidth),
        typographyScale: this._resolveTypographyScale(viewportWidth),
        worldScale: this._resolveWorldScale(viewportWidth),
      },
    };
  }

  private _createEnvironmentInput(
    viewportWidth: number,
    viewportHeight: number,
    devicePixelRatio: number,
    isMobile: boolean,
    reducedMotion: boolean,
  ): ResponsiveEnvironmentInput {
    const hardwareConcurrency =
      typeof navigator === "undefined"
        ? 8
        : navigator.hardwareConcurrency ?? 8;
    const deviceMemory = this._resolveDeviceMemory();
    return {
      viewportWidth,
      viewportHeight,
      devicePixelRatio,
      isMobile,
      reducedMotion,
      hardwareConcurrency,
      deviceMemory,
    };
  }

  private _resolveBreakpoint(viewportWidth: number): ResponsiveBreakpoint {
    if (viewportWidth < 768) return "mobile";
    if (viewportWidth < 1024) return "tablet";
    if (viewportWidth < 1600) return "desktop";
    return "wide";
  }

  private _resolveViewportScale(viewportWidth: number): number {
    return Helpers.clamp(viewportWidth / DEFAULT_VIEWPORT_WIDTH, 0.72, 1.24);
  }

  private _resolveTypographyScale(viewportWidth: number): number {
    return Helpers.clamp(viewportWidth / 1600, 0.82, 1.08);
  }

  private _resolveWorldScale(viewportWidth: number): number {
    return Helpers.clamp(viewportWidth / 1440, 0.8, 1.12);
  }

  private _prefersReducedMotion(): boolean {
    return this._matchesMedia("(prefers-reduced-motion: reduce)");
  }

  private _matchesMedia(query: string): boolean {
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") {
      return false;
    }
    return window.matchMedia(query).matches;
  }

  private _resolveDeviceMemory(): number | undefined {
    if (typeof navigator === "undefined") return undefined;
    const nav = navigator as Navigator & { deviceMemory?: number };
    return typeof nav.deviceMemory === "number" ? nav.deviceMemory : undefined;
  }

  private _applyCssVariables(snapshot: ResponsiveSnapshot): void {
    if (typeof document === "undefined") return;
    const root = document.documentElement;
    root.style.setProperty("--rvw", String(snapshot.viewportWidth));
    root.style.setProperty("--rvh", String(snapshot.viewportHeight));
    root.style.setProperty("--rdpr", String(snapshot.render.clampedPixelRatio));
    root.style.setProperty("--r-breakpoint", snapshot.breakpoint);
    root.style.setProperty("--r-viewport-scale", String(snapshot.tokens.viewportScale));
    root.style.setProperty(
      "--r-typography-scale",
      String(snapshot.tokens.typographyScale),
    );
    root.style.setProperty("--r-world-scale", String(snapshot.tokens.worldScale));
  }

  private _bindPreferenceListeners(): void {
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") {
      return;
    }
    this._reduceMotionMedia = window.matchMedia("(prefers-reduced-motion: reduce)");
    this._reduceMotionHandler = () => {
      this.updateFromWindow();
    };
    this._reduceMotionMedia.addEventListener("change", this._reduceMotionHandler);
  }

  private static _default: ResponsiveRuntime | null = null;

  static getDefault(): ResponsiveRuntime {
    if (!ResponsiveRuntime._default) {
      ResponsiveRuntime._default = new ResponsiveRuntime();
    }
    return ResponsiveRuntime._default;
  }

  static resetDefault(): void {
    ResponsiveRuntime._default?.dispose();
    ResponsiveRuntime._default = null;
  }
}

